import{_ as t,o as r,c as a,a3 as s}from"./chunks/framework.DdpBa4_E.js";const l="/ReadBooks/assets/974663_img_001.PsOLRzzc.jpg",h=JSON.parse('{"title":"03｜理解、约束、验证：让 AI 可信的三层控制","description":"","frontmatter":{},"headers":[],"relativePath":"books/claude-code-legacy/03-理解约束验证-让-AI-可信的三层控制.md","filePath":"books/claude-code-legacy/03-理解约束验证-让-AI-可信的三层控制.md","lastUpdated":1794316978000}'),n={name:"books/claude-code-legacy/03-理解约束验证-让-AI-可信的三层控制.md"};function e(i,o,p,A,g,d){return r(),a("div",null,[...o[0]||(o[0]=[s('<h1 id="_03-理解、约束、验证-让-ai-可信的三层控制" tabindex="-1">03｜理解、约束、验证：让 AI 可信的三层控制 <a class="header-anchor" href="#_03-理解、约束、验证-让-ai-可信的三层控制" aria-label="Permalink to &quot;03｜理解、约束、验证：让 AI 可信的三层控制&quot;">​</a></h1><p><strong>作者：Robert</strong></p><p>🎧 <strong>文章音频</strong>: [🎧 点击播放：_assets/974663.mp3]</p><blockquote><p>让 AI 看见、让 AI 听话、让 AI 可信。</p></blockquote><p>你好，我是 Robert。</p><p>上一讲结尾我留了一句话：光有分工图还不够，要让 AI 真正可信地帮你干活，还需要一套让它不乱来的框架。</p><p>这一讲就把这套框架给你，名字叫“三层控制”：理解、约束、验证。对应三个动作：<strong>让 AI 看见、让 AI 听话、让 AI 可信</strong>。学完这一讲，你会明白为什么有些人用 Claude Code 用得稳、有些人用得一塌糊涂。差别就在这三层做没做、做到了哪一层。</p><h2 id="为什么光有分工图不够" tabindex="-1">为什么光有分工图不够 <a class="header-anchor" href="#为什么光有分工图不够" aria-label="Permalink to &quot;为什么光有分工图不够&quot;">​</a></h2><p>先说一下问题。上一讲我们把九步分成了三档，第一档让 AI 冲在前面，第二档人机配合，第三档你自己守。</p><p>这张图是对的，但光有它不够。真做起来你会发现一堆问题，问题主要分为三类：</p><ol><li>第一类，你让 AI 读 README、让 AI 梳理接口清单，AI 很认真地干了，但它只看到你给它的那些文件，它不知道你们的某个对接方在生产环境上调用了一个没写在文档里的老接口，AI 连这个接口存在都不知道。<strong>这是最根本的问题：AI 得先能看见完整的项目</strong>。</li><li>第二类，第二档里有“让 AI 动手改代码”这一步，你提一个需求，AI 给你一个方案，你说 OK，AI 开始改。改着改着你会发现，AI 顺手把一段老代码重构了，因为它觉得那段代码“写得不规范”。但你根本没让它动那段代码，它动的那段代码还是核心业务逻辑。<strong>AI 得知道哪些地方不能动</strong>。</li><li>第三类，AI 给你一张架构图，画得挺漂亮，但你怎么知道它画对了？它可能把一个已经废弃的模块画成了核心模块，它可能把一个关键的异步通道漏掉了，它可能把三个表的 JOIN 关系画反了，你凭什么相信这张图？<strong>AI 的产出你得有办法验</strong>。</li></ol><p>这三个问题，对应三层控制要解决的三件事。</p><h2 id="三层控制" tabindex="-1">三层控制 <a class="header-anchor" href="#三层控制" aria-label="Permalink to &quot;三层控制&quot;">​</a></h2><h3 id="第一层-理解-让-ai-看见" tabindex="-1">第一层：理解，让 AI 看见 <a class="header-anchor" href="#第一层-理解-让-ai-看见" aria-label="Permalink to &quot;第一层：理解，让 AI 看见&quot;">​</a></h3><p>理解层要解决的是 AI 的上下文。AI 不是一个自带知识库的工程师，<strong>它是上下文缺失的实习生</strong>。它来的时候是空的。你给它什么，它就能看见什么；你没给的，它看不见。对老项目来说，上下文不只是代码本身。还有：</p><ul><li>项目是干什么的、核心业务场景有哪些</li><li>架构怎么组织、关键模块是什么</li><li>哪些接口对外暴露、哪些是内部的</li><li>数据表之间的关系、核心业务表的字段含义</li><li>代码之外的隐性约定：“这段不要删”、“这个接口对接方 A 在用”</li></ul><p>这些东西，一部分在代码里，一部分在 README 和 wiki 里，还有一部分只在人的脑子里。<strong>理解层要做的事，就是把这些东西整理出来，让 AI 能看见</strong>。</p><p>具体在这门课里，理解层对应几个动作：</p><ul><li>让 AI 先画一份架构全景（ARCHITECTURE.md）</li><li>让 AI 识别出风险地带（哪些地方动了可能出事）</li><li>把以上两份东西翻译成给 AI 看的指令（CLAUDE.md）</li><li>为项目搭起文档骨架（docs 目录），后续逐步填</li></ul><p>后面第二部分会具体展开怎么做。这里只说一件事：<strong>理解层没做扎实，后面两层都是空中楼阁</strong>。AI 都没看见完整的项目，你怎么让它听话？你怎么验证它的产出？</p><h3 id="第二层-约束-让-ai-听话" tabindex="-1">第二层：约束，让 AI 听话 <a class="header-anchor" href="#第二层-约束-让-ai-听话" aria-label="Permalink to &quot;第二层：约束，让 AI 听话&quot;">​</a></h3><p>理解层让 AI 看见项目，但<strong>看见不等于听话</strong>。你有没有经历过这样的场景：你让 AI 改一个小功能，它改完顺手把五个不相关的文件也重构了？或者你让 AI 加一个字段，它给你加上之后还很贴心地“优化”了同一个类的几个老方法？这些都是 AI 自作主张的典型表现。</p><p>AI 的本能是按它理解的“最佳实践”去写代码，但<strong>老项目里很多东西不是按最佳实践写的，是有历史原因的</strong>。AI 不知道这些原因，就按它的判断改，改出来的东西你不想要。</p><p>约束层要做的，就是把“不要改什么、该怎么改、改成什么样”写清楚，让 AI 在你画的框里干活。约束分两种：</p><ol><li><strong>静态约束</strong>：写在 CLAUDE.md、SKILL.md 里的规则。比如“这个类是兼容旧版本的，任何改动都要保持方法签名”；“改代码时只动你要改的文件，不要顺手重构其他文件”；“命名用下划线风格，不用驼峰”。这些规则写进 AI 的上下文，它做事的时候会参照。</li><li><strong>动态约束</strong>：每次让 AI 干活时的即时指令。比如提示词里明确说“只改这三个文件，其他一律不动”；“改之前先跟我确认方案，不要直接动代码”；“有任何不确定的地方停下来问我，不要猜”。这些指令每次都要给，不能指望 AI 自己记住。</li></ol><p><strong>静态约束是长期投资，写一次后面复用。动态约束是每次的具体引导，不能省</strong>。两种加起来，AI 才会真的听话。顺便说一句，Anthropic 官方把这套给 AI 搭约束的工程工作叫 Harness Engineering。Harness 原意是马具，套在马身上让马听话干活，意思很形象。你不需要记这个术语，知道有这么个东西就行。</p><h3 id="第三层-验证-让-ai-可信" tabindex="-1">第三层：验证，让 AI 可信 <a class="header-anchor" href="#第三层-验证-让-ai-可信" aria-label="Permalink to &quot;第三层：验证，让 AI 可信&quot;">​</a></h3><p>AI 看见了、也听话了，是不是就能直接用了？还不行。还差一层：<strong>验证</strong>。</p><p>AI 给你的产出，你不能靠“看起来没问题”来决定它能不能用。你得有一套独立于 AI 的基准，来对它的产出做独立验证。原因很简单：<strong>AI 生成代码的能力很强，但 AI 对代码正确性的判断能力没那么强</strong>。</p><p>它能写出一段 10 行的函数看起来完美契合你的需求，但它可能没考虑到某个边界条件。它可能算对了主流程，但忽略了并发场景。它可能看起来测试都过了，但测试本身就是它自己写的，覆盖不到它没意识到的情况。</p><p>所以验证层要做的，是建立一套 AI 产出之外的基准，用基准来校验 AI。具体有几件事：</p><ul><li><strong>集成测试</strong>：动手改之前，让 AI 先写一套覆盖核心链路的集成测试，锁住现在的行为。改造之后跑一遍，看有没有什么被破坏。</li><li><strong>Characterization Test</strong>：针对那些你说不清逻辑、也没文档的老代码，让 AI 根据当前实际行为写测试。这套测试不保证代码是“对”的，但要保证改之前改之后行为一致。</li><li><strong>独立 review</strong>：改完之后，除了你自己看，再让 AI 用另一个角度（比如从攻击者视角看这段代码有什么漏洞）审一遍自己的产出。</li><li><strong>curl 核对</strong>：接口改造，最后用 curl 跑几个场景对比改造前后的响应。</li></ul><p><strong>验证不是事后补票，是动手前就建好的安全网</strong>。这张网越密，你越敢放手让 AI 做事。</p><h3 id="三层不是孤立的" tabindex="-1">三层不是孤立的 <a class="header-anchor" href="#三层不是孤立的" aria-label="Permalink to &quot;三层不是孤立的&quot;">​</a></h3><p>讲完三层，强调一件事：<strong>它们不是三件独立的事，是一个链条</strong>。</p><p><strong>理解决定约束</strong>。你对项目理解到什么程度，约束才能写到什么程度。连模块关系都没理清，你写不出“这个模块不能依赖那个模块”这种约束。</p><p><strong>约束决定验证</strong>。你约束里明确“核心接口的响应格式不能变”，验证里才会去校验响应格式。约束里没写这一条，验证就不会关注。</p><p><strong>验证反过来补理解</strong>。验证跑完暴露了一个问题，“这段代码改了之后有个很边角的场景炸了”，这个发现会回补到理解层里：原来这段代码还管着那个场景，以后的 CLAUDE.md 要加一条。</p><p>所以这三层转起来之后，<strong>是一个正循环</strong>。理解越深，约束越准；约束越准，验证越有针对性；验证越扎实，对项目的理解又加深一层。</p><p>这个循环转几圈，AI 就从“看起来能用”变成“真的可信”。</p><h2 id="这不是流程-是骨架" tabindex="-1">这不是流程，是骨架 <a class="header-anchor" href="#这不是流程-是骨架" aria-label="Permalink to &quot;这不是流程，是骨架&quot;">​</a></h2><p>还要说一件事。可能有同学读到这儿，心里想：三层控制听起来挺正式的，是不是要我每次改造前先做理解、再做约束、再做验证，走完一整个流程？</p><p><strong>不是。三层不是一个按顺序走的流程，是一个时刻在工作的骨架</strong>。</p><p>什么意思？举个例子。你在改一段代码，过程中 AI 问你“这个字段是什么含义”，你回答了一句。这一句就进入了理解层。这是你对项目理解的一小块，应该沉淀到 CLAUDE.md 里。</p><p>你在提示词里加了一句“不要改测试文件”。这一句就进入了约束层。未来这个约束可能反复用得上。</p><p>你改完跑了一遍测试，发现两个场景还没覆盖，补了两个 case。这两个 case 就进入了验证层。你的安全网又密了一点。</p><p><strong>理解、约束、验证，不是三件你要专门花时间去“建立”的事。是每次你和 AI 协作的时候，都在同时做的三件事</strong>。</p><p>稳定用 AI 的工程师和混乱用 AI 的工程师，差别就在这里：<strong>前者每次协作都是在给三层添砖加瓦；后者每次都是从零开始，一次性用完就扔</strong>。</p><p>这门课后面 30 讲，本质上都在练这三层。第二部分建理解层的骨架，第三部分搭约束层的规则，实战部分每一次改造都在同时走三层。</p><h2 id="映射到九步" tabindex="-1">映射到九步 <a class="header-anchor" href="#映射到九步" aria-label="Permalink to &quot;映射到九步&quot;">​</a></h2><p>最后给你一张图，把三层控制和 01 讲那九步映射起来。</p><p><img src="'+l+'" alt="图片" loading="lazy"></p><p>你会看到一件事：<strong>前六步（了解项目）主要在建理解层，第四、五步（搭环境、访接口）开始带入约束层的影子，第八步（动手改）三层都在同时工作，第九步（验收）验证层唱主角</strong>。</p><p>三层不是先理解、再约束、再验证这种时间顺序。<strong>是九步里每一步都或多或少涉及这三层，只是比重不同</strong>。</p><p>这张图记在心里。后面讲每一步、每一个动作的时候，你都可以对着这张图问自己：这一步主要在做哪一层？我这一层做扎实了没？</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>这一讲讲了整门课最核心的方法论骨架：<strong>三层控制</strong>。</p><ul><li><strong>理解层：让 AI 看见</strong>。上下文越准、越完整，AI 表现越稳。</li><li><strong>约束层：让 AI 听话</strong>。规则越清晰、越具体，AI 越不会乱改。</li><li><strong>验证层：让 AI 可信</strong>。基准越密、越独立，AI 产出越敢用。</li></ul><p>这三层不是三个独立的流程，是一个时刻在工作的骨架。每次你和 AI 协作，都在同时给这三层添砖加瓦。</p><ul><li>稳定用 AI 的工程师，都在这三层上持续投资。</li><li>混乱用 AI 的工程师，要么三层都没建，要么只建了一两层。</li></ul><p>到这里，你可能会觉得 01-03 这三讲讲得有点虚，没怎么动代码。但当你真正进入老项目改造的时候，你会发现，后面 30 讲所有的具体动作，根都在这三讲里。九步链路、三档分工、三层控制，这是整门课方法论的骨架。</p><p>希望你把 01-03 这三讲记在心里，带回到你的改造任务中。内化之后你会发现：<strong>老项目改造没那么复杂，其实都是这套骨架在重复转。</strong></p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><ol><li>回想你最近一次用 Claude Code 改老项目的经历，三层里哪一层做得最扎实、哪一层最薄弱？薄弱那层给你造成了什么问题？</li><li>你现在手上维护的项目，如果要补理解层，你会先补什么？约束层呢？验证层呢？各写 2-3 条具体的、能马上动手做的事。</li></ol><p>欢迎在评论区把你的答案写出来。如果今天的课程让你有所收获，也欢迎转发给有需要的朋友，邀请他来一起学习，我们下节课再见！</p><hr><h2 id="精选评论" tabindex="-1">精选评论 <a class="header-anchor" href="#精选评论" aria-label="Permalink to &quot;精选评论&quot;">​</a></h2><h2 id="yphust-你在改一段代码-过程中-ai-问你-这个字段是什么含义-你回答了一句。这一句就进入了理解层。这是你对项目理解的一小块-应该沉淀到-claude-md-里" tabindex="-1"><strong>yphust</strong>: 你在改一段代码，过程中 AI 问你“这个字段是什么含义”，你回答了一句。这一句就进入了理解层。这是你对项目理解的一小块，应该沉淀到 CLAUDE.md 里 <a class="header-anchor" href="#yphust-你在改一段代码-过程中-ai-问你-这个字段是什么含义-你回答了一句。这一句就进入了理解层。这是你对项目理解的一小块-应该沉淀到-claude-md-里" aria-label="Permalink to &quot;**yphust**: 你在改一段代码，过程中 AI 问你“这个字段是什么含义”，你回答了一句。这一句就进入了理解层。这是你对项目理解的一小块，应该沉淀到 CLAUDE.md 里&quot;">​</a></h2><p>那这个CLAUDE.md得有多长？</p><blockquote><p><strong>作者回复</strong>: 这里想表达的是，CLAUDE.md 是加载的入口。在接下来的文章和流程中，CLAUDE.md 放的是/docs里面文档的说明。也就是链接到真正的docs文件里面对应的详细文档。</p></blockquote><hr><p><strong>重来</strong>: 全文多次提到了 沉淀到 CLAUDE.md，我不理解是想表达沉淀起来，还是实际真的就把任何东西都放到了CLAUDE.md。这个让我有点质疑专业度了</p><blockquote><p><strong>作者回复</strong>: 这里可以看一下第10讲，看是不是符合您的预期～。</p></blockquote><hr><p><strong>许凯</strong>: 利用Obsidian可以很好组合各类markdown文档引用，CLAUDE.md里面放项目全局的描述，主要说明白：是什么（要素和连接关系）、为什么（什么场景下使用达到什么目的，可监控、高安全、高可用、高扩展、高性能、低成本、功能与配置一致单一完整正交等，可以充分发挥模型的能动性）、怎么样（要素和连接关系怎么配合运转起来的、约束、规则。具体的实现步骤可以分要素在引用的文件里面详细说明，保持CLAUDE.md文件的干净简洁）。具体到要素和连接关系的描述文档编写时，也可以按照上面是什么、为什么、怎么样的逻辑进行编写，做到有总有分。</p><blockquote><p><strong>作者回复</strong>: 是的。我也会往CLAUDE.md放一些主要的文档的链接，让项目一启动，就有足够的上下文。 所以在后面在文档维护的时候，就会提示更新claude.md。把文档链接过来，尽量让上下文全，而不用每次都重新输入上下文。</p></blockquote><hr><p><strong>TheOne</strong>: 很有价值，我复盘了一下自己的重构经历，最大的问题其实就是第二步 理解项目应该是50：50，我自己是100：0，我虽然知道ai不理解业务逻辑，只知道实际发生了什么，但还是陷入了陷阱，自己不愿意看代码了，但是我都不去看，就发现不了它是不是在胡说八道</p><blockquote><p><strong>作者回复</strong>: 是的。其实老项目改造的流程就是：先理解、再改、最后验证。而我们对AI能做的就是限制。也就是我们一直在说的SDD。各种SDD 工具、思想。不管是harness、skill、claude.md, spec 都是在说一个事情。 但是回归到本质的流程，还是：理解、改、验证。这三个。 所以在老项目改造中，就是想办法把这三个步骤流程固定下来，流程化。然后效果就会慢慢好起来。</p></blockquote><hr><p><strong>ple</strong>: 有些啰嗦</p>',81)])])}const c=t(n,[["render",e]]);export{h as __pageData,c as default};
